/// <summary>
/// COC of PurchFormLetter
/// </summary>
[ExtensionOf(classStr(PurchFormLetter))]
final class METPurchFormLetter_Extension
{
    public boolean METIsServiceConfirmation;
}

Method.Source:
    /// <summary>
    /// To skip validate from service confirmation
    /// </summary>
    /// <param name = "_isServiceConfirmation">Is called from service</param>
    /// <returns>boolean</returns>
    final public boolean METparmServiceConfirmation(boolean _isServiceConfirmation = METIsServiceConfirmation)
    {
        METIsServiceConfirmation = _isServiceConfirmation;

        return METIsServiceConfirmation;
    }

    /// <summary>
    /// Throws an error when print purchase order enabled for PO Confirmation process, when there is no sub mode on purchase orders.
    /// </summary>
    public void  run()
    {
        if (this.caption() == "@SYS319254" && this.printFormLetter())
        {
            PurchTable purchTable = purchFormLetterContract.parmPurchTable();
            MetPurchTable metPurchTable = MetPurchTable::find(purchTable.PurchId);

            NumberOfRecords recordCnt = VendPurchOrderJour::numberOfPurchaseOrderVersions(purchTable);
            METMultiSelectStringValue multiStrVal;

            if (recordCnt == 0)
            {
                multiStrVal = metPurchTable.POSubMode;
            }
            else
            {
                multiStrVal = metPurchTable.POChngSubMode;
            }

            if (!multiStrVal)
            {
                throw error ("@MET:ErrorPOSubmit");
            }
        }
        next run();
    }

    /// <summary>
    /// Find the substring in a given string.
    /// </summary>
    /// <param name = "_multiStrVal">_multiStrVal</param>
    /// <param name = "_subStr">_subStr</param>
    /// <returns>Integer 0 if not match string, Otherwise greater than 0.</returns>
    static int getPOSubMode(METMultiSelectStringValue _multiStrVal, METMultiSelectStringValue _subStr)
    {
        int len = strLen(_multiStrVal);

        return strScan(_multiStrVal, _subStr, 1, len);
    }
